window.STORY_CHAPTERS["c45e7b042644fcfde"]={"id":"c45e7b042644fcfde","lines":[{"uid":"talk.vc.home_touch_medina_1#originalText","id":"talk.vc.home_touch_medina_1","speaker":{"cn":"梅蒂娜","en":"Medina","ja":"メディナ"},"text":{"cn":"你、你做什么！被你摸头我一点也不开心！","en":"W-What are you doing?! I won't get nicer on you even if you pet me!","ja":"な、何をする!お前に撫でられても嬉しくもなんともない!"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_medina_2#originalText","id":"talk.vc.home_touch_medina_2","speaker":{"cn":"梅蒂娜","en":"Medina","ja":"メディナ"},"text":{"cn":"头发上的尘埃我会自己拿掉。还是说，你该不会有其他目的吧？","en":"I can at least take out the dust from my hair by myself. Or, could there possibly be another signal?","ja":"髪の埃くらい自分で取れるそれとも、まさかほかの意図があるわけではないだろうな?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_medina_3#originalText","id":"talk.vc.home_touch_medina_3","speaker":{"cn":"梅蒂娜","en":"Medina","ja":"メディナ"},"text":{"cn":"够了，你给我住手！你这家伙……做好觉悟了吧？","en":"S-Stop! You...will pay for this!","ja":"よせ、やめろっ!貴様……覚悟はできているんだろうな?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_medina_4#originalText","id":"talk.vc.home_touch_medina_4","speaker":{"cn":"梅蒂娜","en":"Medina","ja":"メディナ"},"text":{"cn":"你那只手是什么意思？要是想比试的话就说吧。","en":"What are you doing with that hand? If you want to fight, you should have said so.","ja":"なんだ、その手は?立ち合って欲しいならそう言えばいい"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_medina_5#originalText","id":"talk.vc.home_touch_medina_5","speaker":{"cn":"梅蒂娜","en":"Medina","ja":"メディナ"},"text":{"cn":"要尝尝我的秘藏奥义吗？要是不想的话就快点收回你那只手。","en":"Would you like for me to use my Secret Technique on you? If not, then I suggest retracting that hand as soon as possible.","ja":"我が秘奥義を叩き込んでやろうか?そうでないなら、さっさとその手を引っこめるがいい"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_nergius_integrator_1#originalText","id":"talk.vc.home_touch_nergius_integrator_1","speaker":{"cn":"涅鲁基乌斯","en":"Nergius","ja":"ネルギウス"},"text":{"cn":"看清楚了，我跟恩特基尔几乎一样高，我绝对没有比他矮。","en":"Look closely. I'm about the same height as Entokia. I am most certainly not shorter.","ja":"よく見ろエントキアとはほぼ同じ身長だ決して私のほうが低いわけではない"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_nergius_integrator_2#originalText","id":"talk.vc.home_touch_nergius_integrator_2","speaker":{"cn":"涅鲁基乌斯","en":"Nergius","ja":"ネルギウス"},"text":{"cn":"不要随便摸我的头。就算你是代表剑士，也不得无礼。","en":"Don't you dare touch my head. Not even the swordsman delegate may invade my personal space.","ja":"気安く私の頭に触れるな代表剣士とはいえ、無礼があれば許さぬ"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_nergius_integrator_3#originalText","id":"talk.vc.home_touch_nergius_integrator_3","speaker":{"cn":"涅鲁基乌斯","en":"Nergius","ja":"ネルギウス"},"text":{"cn":"这是最高司祭为我订制的铠甲，配合我的发色，颜色是草绿。","en":"The High Pontifex custom built my armor. It is dark green, just like my hair.","ja":"これは最高司祭猊下が誂えてくださった鎧私の髪に合わせた、萌黄色だ"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_nergius_integrator_4#originalText","id":"talk.vc.home_touch_nergius_integrator_4","speaker":{"cn":"涅鲁基乌斯","en":"Nergius","ja":"ネルギウス"},"text":{"cn":"要申请决斗是吗？如果砍伤代表剑士无罪，我随时接受挑战。","en":"You wish to duel? If I have permission to kill you, I will gladly accept the challenge.","ja":"決闘の申し込みですか?代表剣士を斬っても良いならいつでも受けて立ちますが"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_nergius_integrator_5#originalText","id":"talk.vc.home_touch_nergius_integrator_5","speaker":{"cn":"涅鲁基乌斯","en":"Nergius","ja":"ネルギウス"},"text":{"cn":"就跟我的萌岚枪一样，用那点力道是推不倒我的。","en":"Just like my Budding Storm Spear, I will not be broken by flimsy attacks such as yours.","ja":"私の萌嵐槍と同じくその程度の力で突かれても倒れることなどない"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_oberon_1#originalText","id":"talk.vc.home_touch_oberon_1","speaker":{"cn":"奥伯龙","en":"Oberon","ja":"オベイロン"},"text":{"cn":"国王需要王冠。虽然是个无聊的把戏，不过看起来还不差。","en":"A king need's his crown. It's a silly thing, but it doesn't look too bad.","ja":"王には王冠が必要だくだらない茶番だが、まあ見た目は悪くない"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_oberon_2#originalText","id":"talk.vc.home_touch_oberon_2","speaker":{"cn":"奥伯龙","en":"Oberon","ja":"オベイロン"},"text":{"cn":"面对国王，你不认为自己头抬太高了吗？快下跪，下等人。","en":"Don't you think you're a little too prideful towards the king? Show some respect, servant.","ja":"王に対して、頭が高いと思わないか?跪きたまえ、下郎"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_oberon_3#originalText","id":"talk.vc.home_touch_oberon_3","speaker":{"cn":"奥伯龙","en":"Oberon","ja":"オベイロン"},"text":{"cn":"唉呀！我不喜欢别人这样碰我。","en":"Oh! I don't like it when someone touches me like that.","ja":"おっとぉ!人からそんな風に触られるのは好きじゃないんでね"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_oberon_4#originalText","id":"talk.vc.home_touch_oberon_4","speaker":{"cn":"奥伯龙","en":"Oberon","ja":"オベイロン"},"text":{"cn":"你自己过来啊。这不是挺积极的吗？难道说，你变心了？","en":"Aren't you a little assertive? Perhaps, a change of heart?","ja":"君の方から、ずいぶん積極的じゃないかもしかして、心変わりかな?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_oberon_5#originalText","id":"talk.vc.home_touch_oberon_5","speaker":{"cn":"奥伯龙","en":"Oberon","ja":"オベイロン"},"text":{"cn":"好美的手啊……若是含进嘴里的话，一定很美味吧……","en":"Such beautiful hands... And these lips... How delectable...","ja":"キレイな手だ……口に含んだらさぞかし美味なんだろうねぇ……"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_oberon_8#originalText","id":"talk.vc.home_touch_oberon_8","speaker":{"cn":"奥伯龙","en":"Oberon","ja":"オベイロン"},"text":{"cn":"想攻击我也没用喔。因为在系统上，我是不会受到伤害的。","en":"Even if you try to attack me, it's pointless. I can't take any damage on the system.","ja":"ぼくに攻撃しようとしても無駄だよシステム上、ぼくはダメージを受けないんだから"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_phillia_1#originalText","id":"talk.vc.home_touch_phillia_1","speaker":{"cn":"菲莉亚","en":"Philia","ja":"フィリア"},"text":{"cn":"等、等等……啊……摸我的头发有这么好玩吗？","en":"W-Wait up... I-I... Is petting my hair fun?","ja":"ちょ、ちょっと……あ……わたしの髪なんか撫でて楽しい?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_phillia_2#originalText","id":"talk.vc.home_touch_phillia_2","speaker":{"cn":"菲莉亚","en":"Philia","ja":"フィリア"},"text":{"cn":"我的头发总是乱翘。好羡慕拥有漂亮直发的人喔～","en":"My hair never stays down... I'm so jealous of girls with beautiful straight hair.","ja":"わたし、くせっ毛なんだよね綺麗なストレートの子はうらやましいなあ"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_phillia_3#originalText","id":"talk.vc.home_touch_phillia_3","speaker":{"cn":"菲莉亚","en":"Philia","ja":"フィリア"},"text":{"cn":"这、这么想摸吗？是没关系啦……但是会害羞耶～","en":"Y-You want to pet my head that bad? You can... but it's embarrassing.","ja":"そ、そんなに撫でたいの?別にいいけど……照れちゃうよ"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_phillia_4#originalText","id":"talk.vc.home_touch_phillia_4","speaker":{"cn":"菲莉亚","en":"Philia","ja":"フィリア"},"text":{"cn":"因为我重视AGI，装备会比较轻一点。","en":"My character specializes in AGI, so my equipment is a little on the lighter side.","ja":"わたしはAGI重視だから装備は少し軽めなんだ"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_phillia_5#originalText","id":"talk.vc.home_touch_phillia_5","speaker":{"cn":"菲莉亚","en":"Philia","ja":"フィリア"},"text":{"cn":"欸，你想摸哪里啊？到这个地步我要生气啰？","en":"Hey, where do you think you're touching? Are you trying to make me mad?","ja":"ねえ、どこ触ろうとしてるの?さすがに怒るよ?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_phillia_6#originalText","id":"talk.vc.home_touch_phillia_6","speaker":{"cn":"菲莉亚","en":"Philia","ja":"フィリア"},"text":{"cn":"真是的……真的很色耶。……你不可以对其他人做这种事喔？","en":"This is... already so dirty ...But you can’t be doing this to other people all right?","ja":"もう……ほんとエッチだよね……ほかの人にやったらダメなんだからね?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_phillia_7#originalText","id":"talk.vc.home_touch_phillia_7","speaker":{"cn":"菲莉亚","en":"Philia","ja":"フィリア"},"text":{"cn":"……你该不会是寂寞了吧？真拿你没办法……只能一下下喔。","en":"...Are you feeling lonely? What am I going to do with you... Just this once, right?","ja":"……もしかして、寂しいの?しょうがないなあ……今だけ、だからね?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_phillia_8#originalText","id":"talk.vc.home_touch_phillia_8","speaker":{"cn":"菲莉亚","en":"Philia","ja":"フィリア"},"text":{"cn":"做那种事，有人会误会的……比方说我……之类的，就会误会。","en":"If you do that, there will be those who will get the wrong idea... For example, like me...","ja":"そういうことすると、勘違いする人がいるから……た、例えば、わたし……とか"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_premiere_1#originalText","id":"talk.vc.home_touch_premiere_1","speaker":{"cn":"普蕾蜜亚","en":"Premiere","ja":"プレミア"},"text":{"cn":"摸头是关系亲密的证明呢。我也想摸摸你的头，请蹲下来一点。","en":"Petting your head is a way of expressing one’s love as a parent. I also want to pet your head. Crouch down a little more, please.","ja":"頭を撫でるのは、親愛の証ですね私も、あなたの頭を撫でたいですもう少し屈んでください"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_premiere_2#originalText","id":"talk.vc.home_touch_premiere_2","speaker":{"cn":"普蕾蜜亚","en":"Premiere","ja":"プレミア"},"text":{"cn":"……再来，请多摸我一点。可以多用点力没关系。","en":"...Please, pet me more. A little stronger would be fine too.","ja":"……もっと、撫でてくださいもっと強くてもいいです"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_premiere_3#originalText","id":"talk.vc.home_touch_premiere_3","speaker":{"cn":"普蕾蜜亚","en":"Premiere","ja":"プレミア"},"text":{"cn":"我的梦想……是不是也和大家一样，是用自己的","en":"Could it be true that everyone envisions this the same way in their own dreams, too?","ja":"私の夢、というのもやはり、みなさんと同じようにこの頭に思い描くものなのでしょうか"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_premiere_4#originalText","id":"talk.vc.home_touch_premiere_4","speaker":{"cn":"普蕾蜜亚","en":"Premiere","ja":"プレミア"},"text":{"cn":"从你的手上传来体温。呵呵……我好开心。","en":"I can feel your body heat from your hand. Hehe... I'm flattered...","ja":"あなたの手から、体温が伝わってきますふふ……それが、うれしい……"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_premiere_5#originalText","id":"talk.vc.home_touch_premiere_5","speaker":{"cn":"普蕾蜜亚","en":"Premiere","ja":"プレミア"},"text":{"cn":"请再抱紧我一点……因为，我是你的情人啊。","en":"Hold me tighter... I am, after all, yours and yours alone.","ja":"もっと、強く抱きしめてください……だって、私はあなたのあいじん、ですから"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_premiere_6#originalText","id":"talk.vc.home_touch_premiere_6","speaker":{"cn":"普蕾蜜亚","en":"Premiere","ja":"プレミア"},"text":{"cn":"你，喜欢再大一点的胸部吗……？","en":"Do you like girl's with slightly bigger chests...?","ja":"あなたは、もう少し大きい胸の方が好きなのでしょうか……?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_premiere_7#originalText","id":"talk.vc.home_touch_premiere_7","speaker":{"cn":"普蕾蜜亚","en":"Premiere","ja":"プレミア"},"text":{"cn":"我也想碰触你。如此一来，便能感受到羁绊……","en":"I also want to touch you. Speaking of which, I feel... a bond.","ja":"私も、あなたに触れたいそうすれば、絆を……感じられます"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_premiere_8#originalText","id":"talk.vc.home_touch_premiere_8","speaker":{"cn":"普蕾蜜亚","en":"Premiere","ja":"プレミア"},"text":{"cn":"哇！？……我稍微吓到了。不过，并不讨厌……","en":"Kyaa!? ...I was a little caught off guard. But, I don't mind...","ja":"きゃっ!?……少し、びっくりしましたでも、イヤではありません……"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_rain_1#originalText","id":"talk.vc.home_touch_rain_1","speaker":{"cn":"伶茵","en":"Rain","ja":"レイン"},"text":{"cn":"这个发箍很可爱吧？咦？像女仆一样吗？","en":"Isn't this headband cute? It's kind of like a maid, right?","ja":"このカチューシャ、かわいいでしょえ、メイドさんっぽい?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_rain_2#originalText","id":"talk.vc.home_touch_rain_2","speaker":{"cn":"伶茵","en":"Rain","ja":"レイン"},"text":{"cn":"突然就摸别人的头……如果对象不是我的话，你早就被骂到臭头了！","en":"Isn't it a little comfortable? To sudden pet your head... If it wasn't mean, I'll get angry!","ja":"いきなり頭を撫でるなんて……あなたじゃなかったら怒ってるところだからね!"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_rain_3#originalText","id":"talk.vc.home_touch_rain_3","speaker":{"cn":"伶茵","en":"Rain","ja":"レイン"},"text":{"cn":"真、真是的……怎么在这种地方，很害羞耶！","en":"I-It's so... embarrassing! And in a place like this!","ja":"も、もう……こんなところで、恥ずかしいでしょ!"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_rain_4#originalText","id":"talk.vc.home_touch_rain_4","speaker":{"cn":"伶茵","en":"Rain","ja":"レイン"},"text":{"cn":"这位客人，禁止触摸喔！再摸下去就不准你入店了！","en":"Hey, no touching allowed! Any more and you'll be outright banned!","ja":"お客様、おさわりは禁止ですよ!これ以上やったら出禁です!"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_rain_5#originalText","id":"talk.vc.home_touch_rain_5","speaker":{"cn":"伶茵","en":"Rain","ja":"レイン"},"text":{"cn":"你也是男孩子呢……真是的，为什么男人总是这样……","en":"Boys... I don't understand any of you, at all...","ja":"あなたも男の子なのね……まったく、男ってどうしてこう……"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_rain_6#originalText","id":"talk.vc.home_touch_rain_6","speaker":{"cn":"伶茵","en":"Rain","ja":"レイン"},"text":{"cn":"欸！停！你把正值青春年华少女的胸部当作什么了！？","en":"Stop it! What did you think a girl's chest would be like!?","ja":"こら、ストップ!年頃の女の子の胸を何だと思ってるの!?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_rain_7#originalText","id":"talk.vc.home_touch_rain_7","speaker":{"cn":"伶茵","en":"Rain","ja":"レイン"},"text":{"cn":"……欸你该不会也对赛玟做了一样的事吧？","en":"...Hey. You’re not doing the same thing to Seven are you?","ja":"……ねえまさかセブンにも同じようなことしてないでしょうね?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_rain_8#originalText","id":"talk.vc.home_touch_rain_8","speaker":{"cn":"伶茵","en":"Rain","ja":"レイン"},"text":{"cn":"你对我的装备有兴趣吗？跟我说一声的话，随时都可以给你看啊。","en":"Are you interested in my equipment? Just ask and I can show you it anytime.","ja":"わたしの装備に興味があるの?言ってくれれば、いつでも見せてあげるのに"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_raios_1#originalText","id":"talk.vc.home_touch_raios_1","speaker":{"cn":"莱欧斯","en":"Raios","ja":"ライオス"},"text":{"cn":"你太狂妄了。看来你还不明白我是谁呢。","en":"You insolent bastard. It seems you don't know who I am.","ja":"不遜だぞ、貴様私が誰だかわかっていないようだな"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_raios_2#originalText","id":"talk.vc.home_touch_raios_2","speaker":{"cn":"莱欧斯","en":"Raios","ja":"ライオス"},"text":{"cn":"你那样瞄准我的头挥棒，真是没气质又不优美。","en":"How dare you touch my head! You, with no finesse or elegance!","ja":"気品も優美さもないそんな棒振りで我が頭を狙うとは"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_raios_3#originalText","id":"talk.vc.home_touch_raios_3","speaker":{"cn":"莱欧斯","en":"Raios","ja":"ライオス"},"text":{"cn":"你应该明白，再靠近我会有什么下场吧？","en":"If you come any closer, do you realize what will happen to you?","ja":"それ以上近づけばどうなるかわかっているだろうな?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_raios_4#originalText","id":"talk.vc.home_touch_raios_4","speaker":{"cn":"莱欧斯","en":"Raios","ja":"ライオス"},"text":{"cn":"我可没低贱到能让你这种人碰，给我识相点。","en":"Scum like you has no right to touch me. Pull back at once.","ja":"貴様ごときが触っていい私ではないわきまえ給え"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_raios_5#originalText","id":"talk.vc.home_touch_raios_5","speaker":{"cn":"莱欧斯","en":"Raios","ja":"ライオス"},"text":{"cn":"唔，突袭太卑鄙了。所以说乡下剑士就是……","en":"Grrr! A sneak attack? That move is illegal! This is why I hate bumpkins.","ja":"むっ、不意打ちとは卑怯なりこれだから田舎剣士は……"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_raios_8#originalText","id":"talk.vc.home_touch_raios_8","speaker":{"cn":"莱欧斯","en":"Raios","ja":"ライオス"},"text":{"cn":"哎呀哎呀，你找我有事吗？","en":"What do you want? Go away.","ja":"おやおや、私に何か用でも?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_renri_1#originalText","id":"talk.vc.home_touch_renri_1","speaker":{"cn":"连利","en":"Renly","ja":"レンリ"},"text":{"cn":"其实我常常会想如果自己可以再长高一点就好了……不过集成骑士不会长高的呢。","en":"If only I was just a little taller ... Unfortunately, Integrity Knights don't get any taller.","ja":"本当は、もう少し背が高ければいいなと思うんだけど……整合騎士は、背が伸びないからね"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_renri_2#originalText","id":"talk.vc.home_touch_renri_2","speaker":{"cn":"连利","en":"Renly","ja":"レンリ"},"text":{"cn":"……我感觉，很久以前也跟谁像这样互相弄乱对方的头发。虽然我想不起来是谁。","en":"...I feel like there was someone who who I messed around with long ago. Who that person was, I can't seem to remember.","ja":"……遠い昔、誰かとこうして髪をいたずらしあった気がする誰とだったか、思い出せないけど"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_renri_3#originalText","id":"talk.vc.home_touch_renri_3","speaker":{"cn":"连利","en":"Renly","ja":"レンリ"},"text":{"cn":"被你碰到头发的话……那个，我觉得有点害羞……","en":"If you touch my hair like that... It's a little embarrassing but...","ja":"君に髪を触られると……その、少し照れるんだけど……"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_renri_4#originalText","id":"talk.vc.home_touch_renri_4","speaker":{"cn":"连利","en":"Renly","ja":"レンリ"},"text":{"cn":"如果我可以再长点肌肉就好了。像贝尔库利阁下跟迪索尔巴德大人一样……","en":"I wish I could gain a little more muscle. Kind of like Bercouli or Deusolbert...","ja":"もう少し筋肉がつけばいいなあベルクーリ閣下や、デュソルバート殿みたいに……"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_renri_5#originalText","id":"talk.vc.home_touch_renri_5","speaker":{"cn":"连利","en":"Renly","ja":"レンリ"},"text":{"cn":"啊，很危险喔。只是碰到双翼刃手指也会被切断的。","en":"Watch out! You'll cut your finger just by touching the Twin Edged Wings.","ja":"おっと、危ないよ雙翼刃は触れるだけで指を落としてしまうから"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_renri_8#originalText","id":"talk.vc.home_touch_renri_8","speaker":{"cn":"连利","en":"Renly","ja":"レンリ"},"text":{"cn":"对、对不起！那个……我只要跟你在一起，我就会心跳加速，真的很不可思议。","en":"S-sorry! Just... My heart starts racing whenever I am with you.","ja":"ご、ごめん!その……君といると、不思議と胸が高鳴ってしまって"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_ronye_1#originalText","id":"talk.vc.home_touch_ronye_1","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"那个，您一直轻拍我的头……我会没办法清扫……","en":"Uh, I can't clean if you keep patting my head.","ja":"その、頭をポンポンされると……清掃が、できません……"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_ronye_2#originalText","id":"talk.vc.home_touch_ronye_2","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"我有哪里不对劲吗！？过来之前，我有好好打理过耶……","en":"Is my hair messed up?! I thought I brushed it before I left home...","ja":"どこかおかしいですか!?こちらに来る前に、ちゃんと整えてきたのですが……"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_ronye_3#originalText","id":"talk.vc.home_touch_ronye_3","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"学长，请问您是不是……比较喜欢跟缇洁一样的长发？","en":"Mentor, do you prefer girls with long hair, like Tiese?","ja":"先輩は、ティーゼみたいに長い髪型のほうが好み……ですか? "},"kind":"dialogue"},{"uid":"talk.vc.home_touch_ronye_4#originalText","id":"talk.vc.home_touch_ronye_4","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"是！如果您有任何要求，请尽管吩咐！","en":"Aye! Your wish is my command!","ja":"はっ! 何かご用命があればなんなりと! "},"kind":"dialogue"},{"uid":"talk.vc.home_touch_ronye_5#originalText","id":"talk.vc.home_touch_ronye_5","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"肚、肚子好痒……不要再搔我了！","en":"Th-that tickles...! You mustn't tickle me anymore!","ja":"お、お腹はくすぐったく……それ以上はダメです! "},"kind":"dialogue"},{"uid":"talk.vc.home_touch_ronye_6#originalText","id":"talk.vc.home_touch_ronye_6","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"学长……你有好好读过禁忌目录吗？","en":"Mentor, have you thoroughly read through the Taboo Index?","ja":"先輩は禁忌目録とか……ちゃんと読んでおられますか? "},"kind":"dialogue"},{"uid":"talk.vc.home_touch_ronye_7#originalText","id":"talk.vc.home_touch_ronye_7","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"被学长这样逗弄，我会……","en":"Mentor, if you do that to me, I...","ja":"先輩にそんなことされたら私は……"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_ronye_8#originalText","id":"talk.vc.home_touch_ronye_8","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"是的，清扫已经完成了！让您久等了！","en":"I have just finished cleaning! Sorry for the delay!","ja":"はい、もう清掃は終わります! おまたせしました! "},"kind":"dialogue"},{"uid":"talk.vc.home_touch_rosalia_1#originalText","id":"talk.vc.home_touch_rosalia_1","speaker":{"cn":"罗莎莉雅","en":"Rosalia","ja":"ロザリア"},"text":{"cn":"居然碰触女性的头发，你还真没教养呢。","en":"Touching a girl's hair... Yeah. That's not sexist.","ja":"女の髪に触るなんてマナーがなってないわね"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_rosalia_2#originalText","id":"talk.vc.home_touch_rosalia_2","speaker":{"cn":"罗莎莉雅","en":"Rosalia","ja":"ロザリア"},"text":{"cn":"我对这个发型可是很讲究的，请你不要把它弄乱。","en":"Hey, I take pride in my hair. Don't mess it up.","ja":"この髪型にはこだわりがあるの乱さないでちょうだい"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_rosalia_3#originalText","id":"talk.vc.home_touch_rosalia_3","speaker":{"cn":"罗莎莉雅","en":"Rosalia","ja":"ロザリア"},"text":{"cn":"呵呵，我这头红发漂亮吧？我懂你想触摸的心情，但可别调皮啊。","en":"Hehe, I know, my red hair is really pretty. I can see why you'd want to touch it, but no messing around, okay?","ja":"ふふ、キレイな赤髪でしょう?触りたくなるのもわかるけどオイタはだめよ"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_rosalia_4#originalText","id":"talk.vc.home_touch_rosalia_4","speaker":{"cn":"罗莎莉雅","en":"Rosalia","ja":"ロザリア"},"text":{"cn":"喂！你在想什么啊，色狼！","en":"Hey! Get your mind out of the gutter, perv!","ja":"ちょっと!何考えてるのよ、スケベ!"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_rosalia_5#originalText","id":"talk.vc.home_touch_rosalia_5","speaker":{"cn":"罗莎莉雅","en":"Rosalia","ja":"ロザリア"},"text":{"cn":"趁我还没砍下你那只手，再多想想吧。","en":"Reconsider where you're putting your hand before I cut it off.","ja":"その手を切り落とされないうちに考え直しなさい"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_rosalia_8#originalText","id":"talk.vc.home_touch_rosalia_8","speaker":{"cn":"罗莎莉雅","en":"Rosalia","ja":"ロザリア"},"text":{"cn":"你就那么想摸吗？……没门，等你赚多一点我再考虑。","en":"You really want to touch me that badly? No dice. Earn more, then I'll consider it.","ja":"そんなに触りたいの?……ダーメ、もっと稼いできたら考えてあげる"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_sachi_1#originalText","id":"talk.vc.home_touch_sachi_1","speaker":{"cn":"幸","en":"Sachi","ja":"サチ"},"text":{"cn":"嘿嘿……被你这样摸着，就会觉得很安心。","en":"Hehehe. Being patted like that makes me feel safe and calm.","ja":"えへへ……そうやって撫でられると、なんだか安心しちゃうの"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_sachi_2#originalText","id":"talk.vc.home_touch_sachi_2","speaker":{"cn":"幸","en":"Sachi","ja":"サチ"},"text":{"cn":"怎么了？我的脸……有哪里奇怪吗？","en":"What's up? Is there something on my face?","ja":"どうしたの?私の顔……どこか変かな?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_sachi_3#originalText","id":"talk.vc.home_touch_sachi_3","speaker":{"cn":"幸","en":"Sachi","ja":"サチ"},"text":{"cn":"我、我没有哭啦！不过……你可以再陪我一下吗？","en":"I...I'm not crying! But...will you stay with me a bit longer?","ja":"な、泣いてないよ!でも……もうちょっと一緒にいてくれる?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_sachi_4#originalText","id":"talk.vc.home_touch_sachi_4","speaker":{"cn":"幸","en":"Sachi","ja":"サチ"},"text":{"cn":"如果穿更厚重的铠甲，或许就比较没那么可怕……可是，我的力量没那么高。","en":"I might be less scared if my armor were heavier... But I'm not strong enough to wear it.","ja":"もっと重い鎧なら、怖くないのかもしれないけど……私、そんなに力を伸ばしてないから"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_sachi_5#originalText","id":"talk.vc.home_touch_sachi_5","speaker":{"cn":"幸","en":"Sachi","ja":"サチ"},"text":{"cn":"当敌人的攻击接近自己，我就会忍不住闭眼。我是有想要改正，可是……","en":"Whenever an enemy attack falls close to me, I always freeze up and close my eyes. I wish I could fix that.","ja":"体の近くに敵の攻撃が来ると思わず目をつぶっちゃうの直したいんだけど……"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_sachi_6#originalText","id":"talk.vc.home_touch_sachi_6","speaker":{"cn":"幸","en":"Sachi","ja":"サチ"},"text":{"cn":"那、那个……我还是，会觉得害羞……","en":"Um, er, you're embarrassing me.","ja":"そ、その……やっぱり恥ずかしい、んだけど……"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_sachi_7#originalText","id":"talk.vc.home_touch_sachi_7","speaker":{"cn":"幸","en":"Sachi","ja":"サチ"},"text":{"cn":"既然你那么坚持……还、还是不行！","en":"Well, if you insist... N-no, never mind!","ja":"どうしてもって言うなら……や、やっぱりダメッ!"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_sachi_8#originalText","id":"talk.vc.home_touch_sachi_8","speaker":{"cn":"幸","en":"Sachi","ja":"サチ"},"text":{"cn":"谢谢你找我说话。我会永远陪着你的。","en":"Thanks for reaching out to me. I'm always here for you.","ja":"声をかけてくれてありがとういつでもそばにいるよ"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_sakuya_1#originalText","id":"talk.vc.home_touch_sakuya_1","speaker":{"cn":"朔夜","en":"Sakuya","ja":"サクヤ"},"text":{"cn":"呵呵，你比我想得还大胆呢。","en":"Hehe. You're a lot bolder than I took you for.","ja":"ふふ、思ったより大胆だな"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_sakuya_2#originalText","id":"talk.vc.home_touch_sakuya_2","speaker":{"cn":"朔夜","en":"Sakuya","ja":"サクヤ"},"text":{"cn":"……你可不要以为，任何人都可以这样对我喔。","en":"Don't think I let just anyone do this to me.","ja":"……誰にでも許すとは思わないでくれよ?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_sakuya_3#originalText","id":"talk.vc.home_touch_sakuya_3","speaker":{"cn":"朔夜","en":"Sakuya","ja":"サクヤ"},"text":{"cn":"很、很痒啦……受不了，你还真喜欢恶作剧。","en":"Haha...that tickles! Man, you really do love messing with people, don't you?","ja":"く、くすぐったいぞ……まったく、イタズラ好きだな、君は"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_sakuya_4#originalText","id":"talk.vc.home_touch_sakuya_4","speaker":{"cn":"朔夜","en":"Sakuya","ja":"サクヤ"},"text":{"cn":"你对我的胸部有兴趣吗？呵呵……真可爱。","en":"Are you really that interested in me? Hehe. Cute.","ja":"私の胸に興味があるのかい?ふふ……かわいいな"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_sakuya_5#originalText","id":"talk.vc.home_touch_sakuya_5","speaker":{"cn":"朔夜","en":"Sakuya","ja":"サクヤ"},"text":{"cn":"在这种地方……还真大胆呢。虽然我对你那点也深感兴趣……","en":"Wow... So bold, considering where we are. Now I'm even more intrigued by you.","ja":"いきなりかい?……大胆だなそんなところも興味深いが……"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_sakuya_8#originalText","id":"talk.vc.home_touch_sakuya_8","speaker":{"cn":"朔夜","en":"Sakuya","ja":"サクヤ"},"text":{"cn":"嘿！接下来换我了。好了，过来这里。","en":"Whoa, not so fast! It's my turn now. Come here!","ja":"おっと!今度は私の番ださあ、こっちに来て"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_scheta_1#originalText","id":"talk.vc.home_touch_scheta_1","speaker":{"cn":"谢达","en":"Sheyta","ja":"シェータ"},"text":{"cn":"……什么？","en":"...What?","ja":"……なに?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_scheta_2#originalText","id":"talk.vc.home_touch_scheta_2","speaker":{"cn":"谢达","en":"Sheyta","ja":"シェータ"},"text":{"cn":"……不要再碰我了。","en":"...Do not touch me.","ja":"……あんまり触らないでほしい"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_scheta_3#originalText","id":"talk.vc.home_touch_scheta_3","speaker":{"cn":"谢达","en":"Sheyta","ja":"シェータ"},"text":{"cn":"……我的头应该没有很硬吧。","en":"...I don't think I'm that stubborn...","ja":"……私の頭はそんなに硬くないと思う……"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_scheta_4#originalText","id":"talk.vc.home_touch_scheta_4","speaker":{"cn":"谢达","en":"Sheyta","ja":"シェータ"},"text":{"cn":"……你这算是什么意思？","en":"...What do you want?","ja":"……なんのつもり?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_scheta_5#originalText","id":"talk.vc.home_touch_scheta_5","speaker":{"cn":"谢达","en":"Sheyta","ja":"シェータ"},"text":{"cn":"……别随便碰我好吗。","en":"...Hands to yourself.","ja":"……気安く触らないでほしい"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_scheta_6#originalText","id":"talk.vc.home_touch_scheta_6","speaker":{"cn":"谢达","en":"Sheyta","ja":"シェータ"},"text":{"cn":"碰我的胸部有趣吗？","en":"Are you amused by touching my chest?","ja":"胸を触って、面白いの?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_scheta_7#originalText","id":"talk.vc.home_touch_scheta_7","speaker":{"cn":"谢达","en":"Sheyta","ja":"シェータ"},"text":{"cn":"……不想被斩的话，就把你的手移开。","en":"...I don't want to cut you so hands off.","ja":"……斬りたくはないから手をどけて"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_scheta_8#originalText","id":"talk.vc.home_touch_scheta_8","speaker":{"cn":"谢达","en":"Sheyta","ja":"シェータ"},"text":{"cn":"我真的不懂这有什么有趣……","en":"What is so amusing? I don't understand, but...","ja":"なにが楽しいのか私には理解しかねるけど……"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_selka_1#originalText","id":"talk.vc.home_touch_selka_1","speaker":{"cn":"赛鲁卡","en":"Selka","ja":"セルカ"},"text":{"cn":"……你不会又想做触犯禁忌目录的事情吧？","en":"I hope you're not planning on doing something that goes against the Taboo Index again.","ja":"……また、禁忌目録に触れるようなことをするんじゃないでしょうね"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_selka_2#originalText","id":"talk.vc.home_touch_selka_2","speaker":{"cn":"赛鲁卡","en":"Selka","ja":"セルカ"},"text":{"cn":"可以的话，你也摸摸其他孩子吧。他们没有爸爸妈妈，很寂寞的……","en":"Could you maybe pat some of the others? They don't have mothers or fathers and they're very lonely.","ja":"よかったら、他の子をなでてあげてお父さんやお母さんがいなくて寂しがってるから……"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_selka_3#originalText","id":"talk.vc.home_touch_selka_3","speaker":{"cn":"赛鲁卡","en":"Selka","ja":"セルカ"},"text":{"cn":"像这样摸摸头，是你家乡的风俗吗？","en":"Is patting heads a customary greeting where you come from?","ja":"そうやって頭を撫でるのはあなたの地方の風習なの?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_selka_4#originalText","id":"talk.vc.home_touch_selka_4","speaker":{"cn":"赛鲁卡","en":"Selka","ja":"セルカ"},"text":{"cn":"喂，你打算摸哪里？","en":"Where do you think you're touching?","ja":"ちょっとどこを触ろうとしているの?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_selka_6#originalText","id":"talk.vc.home_touch_selka_6","speaker":{"cn":"赛鲁卡","en":"Selka","ja":"セルカ"},"text":{"cn":"就算是客人，还是有可以做跟不可以做的事情喔。","en":"Even when you're a guest, some behaviors do cross the line.","ja":"いくらお客様でも、やっていいことと悪いことがあるんですからね"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_selka_7#originalText","id":"talk.vc.home_touch_selka_7","speaker":{"cn":"赛鲁卡","en":"Selka","ja":"セルカ"},"text":{"cn":"一旦违反禁忌目录，就会有大事发生……","en":"If you break the Taboo Index, you'll be gravely punished for it.","ja":"禁忌目録に違反すると大変なことになるんだから……"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_selka_8#originalText","id":"talk.vc.home_touch_selka_8","speaker":{"cn":"赛鲁卡","en":"Selka","ja":"セルカ"},"text":{"cn":"什么事？你要找东西的话，就先去看看架子吧。","en":"What is it? If you're looking for something, why not check the shelf first?","ja":"なあに?探しものなら、まず棚を覗いてみたら?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_seven_1#originalText","id":"talk.vc.home_touch_seven_1","speaker":{"cn":"赛玟","en":"Seven","ja":"セブン"},"text":{"cn":"等一下！可以不要把我当小孩看吗？我已经是优秀的大人了。","en":"Wait a minute! Can you not treat me like a kid? I'm a fully grown adult.","ja":"ちょっと!子ども扱いしないでくれる?もう立派な大人なんだから"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_seven_2#originalText","id":"talk.vc.home_touch_seven_2","speaker":{"cn":"赛玟","en":"Seven","ja":"セブン"},"text":{"cn":"很漂亮吧？嘿嘿，头发是我最自豪的地方～","en":"Isn't my hair beautiful? Hehe, it's my pride and joy.","ja":"きれいな髪でしょ?えへへ、あたしの自慢なんだー"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_seven_3#originalText","id":"talk.vc.home_touch_seven_3","speaker":{"cn":"赛玟","en":"Seven","ja":"セブン"},"text":{"cn":"突、突然就摸头……难道说，日本是这样打招呼的吗！？","en":"W-why are you suddenly petting my head...? Could it be that's how you greet each other in Japan!?","ja":"い、いきなり頭を撫でるなんて……もしかして、日本ではそれが挨拶だったりするの!?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_seven_4#originalText","id":"talk.vc.home_touch_seven_4","speaker":{"cn":"赛玟","en":"Seven","ja":"セブン"},"text":{"cn":"什么，你要抱抱我吗？虽然很高兴啦，不过你绝对是把我当小孩吧！","en":"What, you mean you'll even hug me? I'm flattered, but you think I’m just some kid, don’t you!","ja":"なあに、抱っこでもしてくれるの?うれしいけど、やっぱりあなた子ども扱いしてるでしょ!"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_seven_5#originalText","id":"talk.vc.home_touch_seven_5","speaker":{"cn":"赛玟","en":"Seven","ja":"セブン"},"text":{"cn":"欸，你跟我说好了不是吗？约好两人独处的时候也不会做奇怪的事的。那是骗人的吗？","en":"Hey, you promised me, didn't you? You wouldn’t do anything weird when we’re alone. Was that all a lie?","ja":"ねえ、あたしと約束したわよね?ふたりきりになっても、変なことはしないって。あれは嘘だったの?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_seven_6#originalText","id":"talk.vc.home_touch_seven_6","speaker":{"cn":"赛玟","en":"Seven","ja":"セブン"},"text":{"cn":"反正你一定是胡说什么想养大一点之类的，想借此对我性骚扰吧！性骚扰、性骚扰！","en":"Either you need to grow up or this was plain 'ol sexual harassment! Sexual harassment!","ja":"どうせ、もっと育てーとかセクハラするつもりなんでしょ!セクハラ、セクハラー!"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_seven_7#originalText","id":"talk.vc.home_touch_seven_7","speaker":{"cn":"赛玟","en":"Seven","ja":"セブン"},"text":{"cn":"我也想变大啊，不过体型有变化的话，声音也会跟着变的说～","en":"I want to get bigger too, but if my body changes, so will my voice.","ja":"あたしだって大きくなりたいけど体型が変わると、声もちょっと変わっちゃうのよねー"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_seven_8#originalText","id":"talk.vc.home_touch_seven_8","speaker":{"cn":"赛玟","en":"Seven","ja":"セブン"},"text":{"cn":"什么，想牵手吗？呵呵，可以啊。要一起跳卡秋莎舞吗？","en":"What is it? Do you want to hold hands? Hehe, I don't mind. Will you dance with me during the katyusha?","ja":"なあに、手を繋ぎたいの?ふふっ、いいわよ一緒にカチューシャでも踊る?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_shasta_1#originalText","id":"talk.vc.home_touch_shasta_1","speaker":{"cn":"夏斯达","en":"Shasta","ja":"シャスター"},"text":{"cn":"如果比身体大小，那些食人鬼也毫不逊色。","en":"If we're talking about size, I don't intend to be outdone by those ogres!","ja":"体のでかさだけならオーガの奴らにもそうそう引けを取らんつもりだ"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_shasta_2#originalText","id":"talk.vc.home_touch_shasta_2","speaker":{"cn":"夏斯达","en":"Shasta","ja":"シャスター"},"text":{"cn":"怎么了？我的头上沾到了什么吗？","en":"What's wrong? Is there something on my face?","ja":"どうした、俺の頭に何かついているのか?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_shasta_3#originalText","id":"talk.vc.home_touch_shasta_3","speaker":{"cn":"夏斯达","en":"Shasta","ja":"シャスター"},"text":{"cn":"你竟然会做这种事，真稀奇。","en":"That's kind of out of place for you doing that for me.","ja":"お前からそのようなことをしてくるのは、珍しいな"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_shasta_4#originalText","id":"talk.vc.home_touch_shasta_4","speaker":{"cn":"夏斯达","en":"Shasta","ja":"シャスター"},"text":{"cn":"虽说只有身体强壮也算不上是强大，但能够承受强力的技能和强大的心灵，也只有锻炼过的身体才行。","en":"Strength can't be defined with body alone, but a well-trained body is what supports a strong heart and technique.","ja":"肉体の強靱さだけが強さではないが、強い心や技を支えるのはやはり鍛え上げた肉体だ"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_shasta_5#originalText","id":"talk.vc.home_touch_shasta_5","speaker":{"cn":"夏斯达","en":"Shasta","ja":"シャスター"},"text":{"cn":"你用这种触摸方式，传达不了什么的，再过来一点吧。","en":"I won't understand anything even if you touch me like that! Come closer!","ja":"そんな触り方をしても、何も伝わらんぞもっと近くに来い"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_shasta_8#originalText","id":"talk.vc.home_touch_shasta_8","speaker":{"cn":"夏斯达","en":"Shasta","ja":"シャスター"},"text":{"cn":"很在意铠甲的伤痕吗？有很多人会想要新的铠甲，但我觉得穿习惯了的这个铠甲最好。","en":"Are you worried about cracks on my armor? There are many out there who would want new armor, but I'm used to wearing this so it's the best option for me.","ja":"鎧の傷が気になるか?新品の鎧を欲しがる奴も多いが俺には着慣れたこいつが一番いいんだ"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_shionne_1#originalText","id":"talk.vc.home_touch_shionne_1","speaker":{"cn":"希侬","en":"Shionne","ja":"シオン"},"text":{"ja":"欠番"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_shionne_2#originalText","id":"talk.vc.home_touch_shionne_2","speaker":{"cn":"希侬","en":"Shionne","ja":"シオン"},"text":{"ja":"欠番"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_silica_1#originalText","id":"talk.vc.home_touch_silica_1","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"你觉得这个发饰如何？希望还算适合我……","en":"What do you think of this hair pin? I hope it looks okay.","ja":"この髪飾り、どうですか? 似合っているといいんですけど……"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_silica_2#originalText","id":"talk.vc.home_touch_silica_2","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"那个，请摸摸我的头……唔唔……","en":"So, uh, you're patting my head...","ja":"あの、頭をなでて……うう……"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_silica_3#originalText","id":"talk.vc.home_touch_silica_3","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"感觉你把我当小孩子看待……不过我很开心。","en":"I feel like a kid again... But it still feels nice.","ja":"なんか子ども扱いですけど……でも、うれしいです"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_silica_4#originalText","id":"talk.vc.home_touch_silica_4","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"那、那个……有点吓到我了。","en":"So, uh, hey... You're freaking me out a little.","ja":"あ、あの……ちょっと、びっくりしちゃいました"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_silica_5#originalText","id":"talk.vc.home_touch_silica_5","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"呀！？你这样很像毕娜喔！调皮成这样……","en":"Eek?! You remind me of Pina! Rough-housing with me like that...","ja":"きゃん!?なんだか、ピナみたいですよ! そんなにじゃれて……"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_silica_6#originalText","id":"talk.vc.home_touch_silica_6","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"再怎么说也不可以那么做啦……因为，我啊……","en":"So, uh, you can't touch me there. Because, I, you know...","ja":"それは、さすがにダメですよ……だって、あたし……"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_silica_7#originalText","id":"talk.vc.home_touch_silica_7","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"那个……就算是我，也是会生气的喔……","en":"Um...even I have a breaking point.","ja":"あの……いくらあたしでも怒りますよ……"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_silica_8#originalText","id":"talk.vc.home_touch_silica_8","speaker":{"cn":"西莉卡","en":"Silica","ja":"シリカ"},"text":{"cn":"是，有什么事吗？不论什么事都尽管说喔。","en":"Yes, what is it? Say anything!","ja":"はい、なんですか? 何でも言ってくださいね"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_sinon_1#originalText","id":"talk.vc.home_touch_sinon_1","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"喂！你不要随便碰我啦！","en":"Hey! Hands to yourself!","ja":"ちょっと! 気安く触らないでよね! "},"kind":"dialogue"},{"uid":"talk.vc.home_touch_sinon_2#originalText","id":"talk.vc.home_touch_sinon_2","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"这副眼镜没有度数。我戴它，是因为当成护身符……","en":"My glasses are non-prescription. I wear them for protection...","ja":"眼鏡には、度は入ってないのこれは、お守りだから……"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_sinon_3#originalText","id":"talk.vc.home_touch_sinon_3","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"别弄，很痒啦……这种事，你应该没有对其他人做吧？","en":"Hey, that tickles! You don't treat other girls like this, do you?","ja":"ちょっと、くすぐったいってば……そういうこと、ほかの子にもしてるんじゃないでしょうね? "},"kind":"dialogue"},{"uid":"talk.vc.home_touch_sinon_4#originalText","id":"talk.vc.home_touch_sinon_4","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"虽然我以前，确实有靠在你的胸口休息过……但那是在游戏里啦！","en":"Yeah, I did rest against your chest once... But that was inside a VR game!","ja":"確かに、胸にもたれて休んだことはあったけど……あれはゲームの中だから! "},"kind":"dialogue"},{"uid":"talk.vc.home_touch_sinon_5#originalText","id":"talk.vc.home_touch_sinon_5","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"呀！？不要搔我侧腹！你这样是性骚扰耶！","en":"Eek?! Hands off the stomach!","ja":"きゃっ!?脇腹はやめて! セクハラよ? "},"kind":"dialogue"},{"uid":"talk.vc.home_touch_sinon_6#originalText","id":"talk.vc.home_touch_sinon_6","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"……没有下一次了喔。你要是再犯，我就射穿你的手。","en":"I'm not warning you again.. Next time you do that, I'm slapping you.","ja":"……2度目はないからね今度やったら、その手を撃ち抜くから"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_sinon_7#originalText","id":"talk.vc.home_touch_sinon_7","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"你要是真的那么喜欢胸部，就去摸自己的啊。你这个变态！","en":"Why don't you just touch your own chest? You’re a real creep!","ja":"そんなに胸が好きなら自分のを触ってなさいこの変態! "},"kind":"dialogue"},{"uid":"talk.vc.home_touch_sinon_8#originalText","id":"talk.vc.home_touch_sinon_8","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"你不用那样拉我，我有听到啦！","en":"Don't tug. I can hear you just fine!","ja":"そんなに引っ張らなくても聞こえてるわよ! "},"kind":"dialogue"},{"uid":"talk.vc.home_touch_siune_1#originalText","id":"talk.vc.home_touch_siune_1","speaker":{"cn":"朱涅","en":"Siune","ja":"シウネー"},"text":{"cn":"怎么了？你真爱撒娇呢。","en":"What's wrong? Somebody sure is needy.","ja":"どうしたの?甘えん坊さんですね"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_siune_2#originalText","id":"talk.vc.home_touch_siune_2","speaker":{"cn":"朱涅","en":"Siune","ja":"シウネー"},"text":{"cn":"就说很痒啦。讨厌……","en":"Hey! That tickles!","ja":"くすぐったいってばもう……"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_siune_3#originalText","id":"talk.vc.home_touch_siune_3","speaker":{"cn":"朱涅","en":"Siune","ja":"シウネー"},"text":{"cn":"我也摸摸你吧。来，过来我这里。","en":"I'll pet you too. Come here.","ja":"私もなでてあげますよほら、おいで"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_siune_4#originalText","id":"talk.vc.home_touch_siune_4","speaker":{"cn":"朱涅","en":"Siune","ja":"シウネー"},"text":{"cn":"呵呵呵，要我抱抱你吗？","en":"Hehe. Want me to hold you?","ja":"ふふふ、抱っこしてあげましょうか?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_siune_5#originalText","id":"talk.vc.home_touch_siune_5","speaker":{"cn":"朱涅","en":"Siune","ja":"シウネー"},"text":{"cn":"别担心，我就在这里喔。","en":"Don't worry. I'm here for you.","ja":"大丈夫、私はここにいますよ"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_siune_8#originalText","id":"talk.vc.home_touch_siune_8","speaker":{"cn":"朱涅","en":"Siune","ja":"シウネー"},"text":{"cn":"嗯？你叫我吗？","en":"Hm? Did you call me?","ja":"ん?私のこと呼びましたか?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_sortiliena_1#originalText","id":"talk.vc.home_touch_sortiliena_1","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"我之所以把头发扎成一束，是因为这样比较方便战斗。","en":"I like my hair tied back because it's easier to fight this way.","ja":"髪をひとつにまとめているのはこの方が戦いやすいからだ"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_sortiliena_2#originalText","id":"talk.vc.home_touch_sortiliena_2","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"你这样逗弄，简直显得我是学妹一样。稍微守点分寸吧。","en":"When you treat me like that, it’s like you don’t see me as your mentor. Show a little more respect.","ja":"そんなことをされるとまるで私が後輩じゃないか少しはわきまえろ"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_sortiliena_3#originalText","id":"talk.vc.home_touch_sortiliena_3","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"要、要是这种事情被其他练士看到……不行啊！","en":"If other disciples saw this... I would be a laughing stock!","ja":"こ、こんなところをほかの練士に見られたら……困る! "},"kind":"dialogue"},{"uid":"talk.vc.home_touch_sortiliena_4#originalText","id":"talk.vc.home_touch_sortiliena_4","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"你那是在做什么？是想要来一场点到为止的比试吗？","en":"Just what do you think you're doing? What do you mean, you want to have a stop short duel?","ja":"それはなんの真似だ? 寸止めの立ち合いをしたいということか? "},"kind":"dialogue"},{"uid":"talk.vc.home_touch_sortiliena_5#originalText","id":"talk.vc.home_touch_sortiliena_5","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"看着你的手，就能明白你至今挥了多少次剑。","en":"One look at your hands, and I can tell how long you've been swinging a sword.","ja":"お前の手を見ればどれほど剣を振ってきたのかわかる"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_sortiliena_6#originalText","id":"talk.vc.home_touch_sortiliena_6","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"就算是我，也知道触碰那部位的意思……所以，快住手！","en":"I know what it means to be touched there. I wasn't born yesterday... So please, stop it!","ja":"私だって、そこを触れることの意味くらいはわかる……だから、やめろ! "},"kind":"dialogue"},{"uid":"talk.vc.home_touch_sortiliena_7#originalText","id":"talk.vc.home_touch_sortiliena_7","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"到此为止了，你不准再碰我。","en":"That's enough. No more touching.","ja":"そこまでだそれ以上、私の体に触れるな"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_sortiliena_8#originalText","id":"talk.vc.home_touch_sortiliena_8","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"怎么了？如果工作已经做完，你今天就可以先回去了。","en":"What is it? If you've finished your work, then you may go home now.","ja":"どうした? 仕事が終わったなら今日はもう帰って構わないぞ"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_sortiliena_child_1#originalText","id":"talk.vc.home_touch_sortiliena_child_1","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"像这样被人摸摸头，还是第一次呢……","en":"I've never had my head patted like this before.","ja":"こんな風に頭を撫でられるのは初めてだ……"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_sortiliena_child_2#originalText","id":"talk.vc.home_touch_sortiliena_child_2","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"我觉得好痒，快住手！","en":"That tickles, stop it!","ja":"なんか、むずむずするからやめろっ! "},"kind":"dialogue"},{"uid":"talk.vc.home_touch_sortiliena_child_3#originalText","id":"talk.vc.home_touch_sortiliena_child_3","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"上段攻击很有威力……但容易躲开。","en":"Attacks from above are powerful, but they're easy to dodge.","ja":"上段からの攻撃は威力はあるが……避けられやすいんだ"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_sortiliena_child_4#originalText","id":"talk.vc.home_touch_sortiliena_child_4","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"喝！那种程度，小孩子也躲得开！","en":"Hah! Even a kid could dodge your flimsy attacks!","ja":"ハッ! その程度なら、子どもでも避けられる! "},"kind":"dialogue"},{"uid":"talk.vc.home_touch_sortiliena_child_5#originalText","id":"talk.vc.home_touch_sortiliena_child_5","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"我想应该没弄脏吧？有哪里奇怪吗？","en":"I don't think your hand is dirty, but... this is weird.","ja":"別に汚れてはいないと思うがおかしかった? "},"kind":"dialogue"},{"uid":"talk.vc.home_touch_sortiliena_child_6#originalText","id":"talk.vc.home_touch_sortiliena_child_6","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"你到底在做什么？","en":"What in the world are you doing?","ja":"いったい何をしているのだ? "},"kind":"dialogue"},{"uid":"talk.vc.home_touch_sortiliena_child_7#originalText","id":"talk.vc.home_touch_sortiliena_child_7","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"你是不是在想什么奇怪的事情？表情很下流喔。","en":"Are you having inappropriate thoughts? You have a devious grin on your face.","ja":"なにかおかしなことを考えてないか? 顔がいやらしいぞ? "},"kind":"dialogue"},{"uid":"talk.vc.home_touch_sortiliena_child_8#originalText","id":"talk.vc.home_touch_sortiliena_child_8","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"嗯？什么事？如果是要比划剑术，我随时奉陪！","en":"A duel, you say?! I would love to fight you, anytime!","ja":"ん、なあに?剣の手合わせなら、いつでも応じるぞ!"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_strea_1#originalText","id":"talk.vc.home_touch_strea_1","speaker":{"cn":"斯朵蕾雅","en":"Strea","ja":"ストレア"},"text":{"cn":"嗯？你要摸摸我吗？","en":"Hm? Could you pet me?","ja":"ん?ナデナデしてくれるの?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_strea_2#originalText","id":"talk.vc.home_touch_strea_2","speaker":{"cn":"斯朵蕾雅","en":"Strea","ja":"ストレア"},"text":{"cn":"欸嘿嘿……被摸头的感觉还不错。","en":"Hehe... Having your head pet feel's pretty good, doesn't it?","ja":"えへへ……頭撫でられるのって気持ちいいよね"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_strea_3#originalText","id":"talk.vc.home_touch_strea_3","speaker":{"cn":"斯朵蕾雅","en":"Strea","ja":"ストレア"},"text":{"cn":"谢谢！这次轮到我了呢。来，快把头靠过来！","en":"Thank you! Next up will be me then. Hey, stick out your head!","ja":"ありがとっ!次はアタシの番だねほら、頭出して!"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_strea_4#originalText","id":"talk.vc.home_touch_strea_4","speaker":{"cn":"斯朵蕾雅","en":"Strea","ja":"ストレア"},"text":{"cn":"呵呵呵，果然会在意那里啊～毕竟是男孩子嘛～","en":"Heheh, as I suspected. You would be curious about something like that.","ja":"むふふ、やっぱりそこが気になっちゃうかーオトコノコだなー"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_strea_5#originalText","id":"talk.vc.home_touch_strea_5","speaker":{"cn":"斯朵蕾雅","en":"Strea","ja":"ストレア"},"text":{"cn":"哇！？真是的……要摸的时候，要先说一声才行啊！","en":"Kyaa?! ...Tell me before you touch me!","ja":"きゃっ!?もう……触るときは最初に触るって言ってくれないと!"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_strea_6#originalText","id":"talk.vc.home_touch_strea_6","speaker":{"cn":"斯朵蕾雅","en":"Strea","ja":"ストレア"},"text":{"cn":"唉呀，今天难得这么大胆呢。呵呵，再多摸一下也可以喔？","en":"You're awfully bold today. Hehe, go ahead. I won’t stop you.","ja":"おやぁ、今日はめずらしく大胆だねんふふ、もっと触ってくれていいよ?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_strea_7#originalText","id":"talk.vc.home_touch_strea_7","speaker":{"cn":"斯朵蕾雅","en":"Strea","ja":"ストレア"},"text":{"cn":"就算是这样的我，也传达地到吗？心脏跳动的声音……","en":"Even like this, I wonder if you hear... the beating of my heart.","ja":"こんなアタシでも、心臓の音……伝わってるかな?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_strea_8#originalText","id":"talk.vc.home_touch_strea_8","speaker":{"cn":"斯朵蕾雅","en":"Strea","ja":"ストレア"},"text":{"cn":"什么什么，找我出任务？我随时欢迎喔－－！","en":"What is it? Is this an invitation for a quest? I'm also open to those!","ja":"なになに、クエストのお誘い?アタシなら、いつでも歓迎だよー!"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_subtilizer_1#originalText","id":"talk.vc.home_touch_subtilizer_1","speaker":{"ja":"サトライザー"},"text":{"ja":"何をしているその醜悪な手を一刻も早く下げろ"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_subtilizer_3#originalText","id":"talk.vc.home_touch_subtilizer_3","speaker":{"ja":"サトライザー"},"text":{"ja":"なんのつもりだ?誰の命令か言ってみろ"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_subtilizer_8#originalText","id":"talk.vc.home_touch_subtilizer_8","speaker":{"ja":"サトライザー"},"text":{"ja":"その程度の攻撃で倒れるとでも思っているのか?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_suguha_1#originalText","id":"talk.vc.home_touch_suguha_1","speaker":{"cn":"直叶","en":"Suguha","ja":"直葉"},"text":{"cn":"咦，什么……？你、你突然这样吓到我了……","en":"Huh? What?! J-jeez. You startled me.","ja":"え、なに……? い、いきなりはびっくりするよ……"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_suguha_2#originalText","id":"talk.vc.home_touch_suguha_2","speaker":{"cn":"直叶","en":"Suguha","ja":"直葉"},"text":{"cn":"小时候，我常常要你这样摸我呢……","en":"When I was a baby, you used to pat my head like this a lot.","ja":"ちっちゃい頃は、こうやってよく撫でてもらったよね……"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_suguha_3#originalText","id":"talk.vc.home_touch_suguha_3","speaker":{"cn":"直叶","en":"Suguha","ja":"直葉"},"text":{"cn":"讨厌，很痒啦！看我怎么回敬你！","en":"Hey! That tickles! Aha! The tables have turned!","ja":"もう、くすぐったいってば! この、お返しだ! "},"kind":"dialogue"},{"uid":"talk.vc.home_touch_suguha_4#originalText","id":"talk.vc.home_touch_suguha_4","speaker":{"cn":"直叶","en":"Suguha","ja":"直葉"},"text":{"cn":"那个……你不要一直盯着我看啦。……真有那么引人注目吗？","en":"Uh...could you, like, not stare at me? Unless...do I really stand out that much?","ja":"あの……ジロジロ見ないでね……やっぱり、そんなに目立つ? "},"kind":"dialogue"},{"uid":"talk.vc.home_touch_suguha_5#originalText","id":"talk.vc.home_touch_suguha_5","speaker":{"cn":"直叶","en":"Suguha","ja":"直葉"},"text":{"cn":"咿啊啊！你知道那里是我的弱点吧！？","en":"Eeep! You know that's my weak spot, don't you?!","ja":"ひゃああっ! そこは弱点だって知ってるでしょ!?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_suguha_6#originalText","id":"talk.vc.home_touch_suguha_6","speaker":{"cn":"直叶","en":"Suguha","ja":"直葉"},"text":{"cn":"喂！？我、我还是很在意的，不要捉弄我啦……","en":"Whoa, dude?! I may not look it, but I'm pretty self-conscious. So, don't tease me.","ja":"ちょっと!?こ、これでも気にしてるんだからからかわないでよ……"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_suguha_7#originalText","id":"talk.vc.home_touch_suguha_7","speaker":{"cn":"直叶","en":"Suguha","ja":"直葉"},"text":{"cn":"喂！就算我们是家人，还是有不能摸的地方啦！","en":"Hey! Even though we're family, there's still \"good touch\" and \"bad touch\"!","ja":"こら! いくら家族でも、触ったらダメなところもあるんだから! "},"kind":"dialogue"},{"uid":"talk.vc.home_touch_suguha_8#originalText","id":"talk.vc.home_touch_suguha_8","speaker":{"cn":"直叶","en":"Suguha","ja":"直葉"},"text":{"cn":"怎么了？你要出门吗？","en":"What's up? Going out somewhere?","ja":"どうしたの? どこかにお出かけする? "},"kind":"dialogue"},{"uid":"talk.vc.home_touch_tiese_1#originalText","id":"talk.vc.home_touch_tiese_1","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"学长！？您这样，太大胆了……","en":"Oh, Mentor?! How...bold of you!","ja":"先輩!?そんな、大胆な……"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_tiese_2#originalText","id":"talk.vc.home_touch_tiese_2","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"其实，我有点憧憬罗妮耶那头乌黑秀发……","en":"Ronie's black hair is so pretty. To be honest, I've always been a little jealous.","ja":"ロニエのキレイな髪色実はちょっと憧れているんです……"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_tiese_3#originalText","id":"talk.vc.home_touch_tiese_3","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"学、学长……我也可以……碰触学长的头发吗？","en":"M-may I also touch your hair?","ja":"せ、先輩……あたしも、先輩の髪……触ってもよろしいですか? "},"kind":"dialogue"},{"uid":"talk.vc.home_touch_tiese_4#originalText","id":"talk.vc.home_touch_tiese_4","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"怎么了，学长？如果有烦恼，请您要跟我说喔。","en":"What's the matter? If something is troubling you, please tell me.","ja":"どうしました、先輩? 困ったことがあったらおっしゃってくださいね"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_tiese_5#originalText","id":"talk.vc.home_touch_tiese_5","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"学长……您是打算摸哪里？","en":"Where do you think you're touching?","ja":"先輩……どこを触ろうとしているのでしょうか"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_tiese_6#originalText","id":"talk.vc.home_touch_tiese_6","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"学长，您的心意我很开心，但别在这种地方……","en":"I appreciate the sentiment, but this is neither the time nor the place.","ja":"先輩、お気持ちはうれしいですが……ここでは"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_tiese_7#originalText","id":"talk.vc.home_touch_tiese_7","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"……我会误会的喔。","en":"I think...you're misinterpreting the situation.","ja":"……勘違い、してしまいますよ"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_tiese_8#originalText","id":"talk.vc.home_touch_tiese_8","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"是的，房间清扫完成了。非常抱歉，花了很多时间。","en":"There! I've finished cleaning your room. Sorry it took so long.","ja":"はい、お部屋の清掃は終わりましたお時間がかかって申し訳ございません"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_tiese_child_1#originalText","id":"talk.vc.home_touch_tiese_child_1","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"我、我已经不是小孩子了！","en":"I-I'm not a kid anymore!","ja":"あ、あたしはもう子どもではありませんよ!"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_tiese_child_2#originalText","id":"talk.vc.home_touch_tiese_child_2","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"头发……留长比较像女孩子吧？","en":"If...I grew out my hair, that would be more lady-like, right?","ja":"髪……伸ばした方が女の子っぽいでしょうか"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_tiese_child_3#originalText","id":"talk.vc.home_touch_tiese_child_3","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"被人摸摸头感觉也不讨厌……","en":"I...don't hate... having my head patted...","ja":"頭を撫でられるのは嫌いでは、ないです……"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_tiese_child_4#originalText","id":"talk.vc.home_touch_tiese_child_4","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"想用剑一较高下吗？是的话，我乐意奉陪！","en":"A sword contest? It would be a pleasure!","ja":"剣の手合わせですか?ならば、喜んで!"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_tiese_child_5#originalText","id":"talk.vc.home_touch_tiese_child_5","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"难道说，你的手很痛吗？我来帮你看一下吧。","en":"Does your hand hurt? I'll take a look at it for you.","ja":"もしかして、手が痛いんですか?少し見てあげますね"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_tiese_child_6#originalText","id":"talk.vc.home_touch_tiese_child_6","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"我的肩膀上沾到了什么吗？可能是练习时弄脏的吧。","en":"Is there something on my shoulder? I wonder if it got dirty during training?","ja":"肩に何かついていますか?稽古で汚れたのかなあ"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_tiese_child_7#originalText","id":"talk.vc.home_touch_tiese_child_7","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"有人曾经跟我说过身体的中线就是要害。","en":"I was taught that a body's midline is a fatal spot.","ja":"体の正中線は急所そう教わりました"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_tiese_child_8#originalText","id":"talk.vc.home_touch_tiese_child_8","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"要是其他人这样做我会觉得很讨厌……但是你的话很不可思议地我并不讨厌。","en":"I don't like it when other people do that to me...but for some weird reason, you're an exception","ja":"ほかの人にされるのはイヤだけど……あなたは不思議とイヤじゃないです"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_vassago_1#originalText","id":"talk.vc.home_touch_vassago_1","speaker":{"cn":"瓦沙克","en":"Vassago","ja":"ヴァサゴ"},"text":{"cn":"想看兜帽下的我吗？好啊，要是你把你的性命交给我的话就让你看吧。","en":"Do you want to look under the hood? No problem. All I ask for is your life in exchange.","ja":"フードの下を見たいか?いいぜぇ、お前の命をくれるんならな"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_vassago_2#originalText","id":"talk.vc.home_touch_vassago_2","speaker":{"cn":"瓦沙克","en":"Vassago","ja":"ヴァサゴ"},"text":{"cn":"头其实意外地难以瞄准，因为总是在动。想打中的话就瞄准肚子吧。","en":"Aiming for the head is harder than I expected. Because it's always moving around. Aim for the stomach if you can.","ja":"頭ってのは、案外狙いにくいんだよく動くからなぁやるんなら、腹を狙いな"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_vassago_3#originalText","id":"talk.vc.home_touch_vassago_3","speaker":{"cn":"瓦沙克","en":"Vassago","ja":"ヴァサゴ"},"text":{"cn":"在这里杀了我也是没用的。无论多少次，我都会潜行来见你的。","en":"Even if you kill me here, it's pointless. No matter how many times you dive at me, I will be there to confront you!","ja":"ここで俺を殺しても無駄だ何度だってダイブしてお前に会いに来てやるよ"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_vassago_4#originalText","id":"talk.vc.home_touch_vassago_4","speaker":{"cn":"瓦沙克","en":"Vassago","ja":"ヴァサゴ"},"text":{"cn":"不错！总是瞄准我的要害……战斗就是要这样才对！","en":"Splendid! Now I can aim at your weak point precisely... That's the rule of combat!","ja":"いいねぇ!急所を的確についてきやがる……戦いはそうでなくちゃあな!"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_vassago_5#originalText","id":"talk.vc.home_touch_vassago_5","speaker":{"cn":"瓦沙克","en":"Vassago","ja":"ヴァサゴ"},"text":{"cn":"要杀我的话，就来瞄准我的心脏吧。我也会瞄准同样的地方。","en":"If you're going to do it, aim for the heart. Because that's where I'll be aiming.","ja":"やるなら、心臓を狙って来いよ俺も同じ場所を狙ってやるからさ"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_vassago_8#originalText","id":"talk.vc.home_touch_vassago_8","speaker":{"cn":"瓦沙克","en":"Vassago","ja":"ヴァサゴ"},"text":{"cn":"很好，我来当你的对手吧。作为代价，千万别以为可以死得轻松！","en":"Very well, I will be your opponent! In exchange, don't think for a minute that your death will be painless!","ja":"いいぜ、相手してやるよその代わり、楽に死ねるとは思わないでくれよなぁ!"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_vector_1#originalText","id":"talk.vc.home_touch_vector_1","speaker":{"cn":"Subtilizer","en":"Subtilizer"},"text":{"cn":"你在做什么，给我赶快收下你那丑陋的手。","en":"What are you doing? Put those filthy hands away!"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_vector_3#originalText","id":"talk.vc.home_touch_vector_3","speaker":{"cn":"Subtilizer","en":"Subtilizer"},"text":{"cn":"你打算做什么？快说是谁下的命令。","en":"What do you want? Who is giving you orders?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_vector_8#originalText","id":"talk.vc.home_touch_vector_8","speaker":{"cn":"Subtilizer","en":"Subtilizer"},"text":{"cn":"你不会以为就这点程度的攻击我就会倒下吧？","en":"Did you honestly think that an attack like that would take me down?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_volo_1#originalText","id":"talk.vc.home_touch_volo_1","speaker":{"cn":"涡罗","en":"Volo","ja":"ウォロ"},"text":{"cn":"摸头这种失礼行为，你打算怎么跟我赔罪？","en":"You touched my head. How do you wish to apologize for your rudeness?","ja":"頭を触るなどという非礼どう詫びるつもりだ?"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_volo_2#originalText","id":"talk.vc.home_touch_volo_2","speaker":{"cn":"涡罗","en":"Volo","ja":"ウォロ"},"text":{"cn":"那种斩击是打不到我的。可别把我看扁了。","en":"That slashing attack will not work on me. I wish you wouldn't underestimate me.","ja":"そんな斬撃は当たらぬあまり私を甘く見るな"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_volo_3#originalText","id":"talk.vc.home_touch_volo_3","speaker":{"cn":"涡罗","en":"Volo","ja":"ウォロ"},"text":{"cn":"要是我想，就躲得开。我刚刚是故意不躲。","en":"If you think of dodging, you will. That's why you couldn't dodge it.","ja":"かわそうと思えばかわせるあえてかわさなかったのだ"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_volo_4#originalText","id":"talk.vc.home_touch_volo_4","speaker":{"cn":"涡罗","en":"Volo","ja":"ウォロ"},"text":{"cn":"如果你想要跟我比试，也只能奉陪。","en":"If you wish to duel, then that is inevitable.","ja":"お前が立ち合いを望むのなら是非もない"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_volo_5#originalText","id":"talk.vc.home_touch_volo_5","speaker":{"cn":"涡罗","en":"Volo","ja":"ウォロ"},"text":{"cn":"那记攻击，就是那什么《艾恩葛朗特流》吗？","en":"So, your attacks are \"Aincrad style,\" you say?","ja":"その攻撃が《アインクラッド流》とやらか"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_volo_8#originalText","id":"talk.vc.home_touch_volo_8","speaker":{"cn":"涡罗","en":"Volo","ja":"ウォロ"},"text":{"cn":"我很忙的，有什么事就快点说。","en":"I am a busy man. If you want something, spit it out.","ja":"私は忙しいのだ用があるなら早く言いたまえ"},"kind":"dialogue"},{"uid":"talk.vc.home_touch_yui_1#originalText","id":"talk.vc.home_touch_yui_1","speaker":{"cn":"结衣","en":"Yui","ja":"ユイ"},"text":{"cn":"嘿嘿……请再多摸摸我！","en":"Hehe... More pats, please?","ja":"えへへ……もっとなでてください!"},"kind":"dialogue"}]};
